import React, { useEffect, useState } from 'react';
import StatCard from '../components/StatCard';
import QuickAction from '../components/QuickAction';
import ActivityFeed from '../components/ActivityFeed';
// import './DashboardPage.css'; // optional for custom styling

export default function DashboardPage() {
  const [stats, setStats] = useState({ dashboards: 0, bookmarks: 0, uploads: 0, reports: 0 });
  const [activities, setActivities] = useState([]);

  useEffect(() => {
    // Replace with Amplify API call later
    setStats({ dashboards: 12, bookmarks: 28, uploads: 5, reports: 34 });
    setActivities([
      { id: 1, text: 'Created dashboard “Mental Health Trends Q1”' },
      { id: 2, text: 'Uploaded “Mental_Health_Survey_Data.xlsx”' },
    ]);
  }, []);

  return (
    <div className="dashboard-container p-6">
      <h1 className="text-xl font-semibold mb-4">Welcome back, Sarah!</h1>

      <div className="grid grid-cols-4 gap-4 mb-6">
        <StatCard label="My Dashboards" value={stats.dashboards} />
        <StatCard label="Bookmarked Datasets" value={stats.bookmarks} />
        <StatCard label="Uploaded Files" value={stats.uploads} />
        <StatCard label="Generated Reports" value={stats.reports} />
      </div>
      <div className="grid grid-cols-4 gap-4 mb-6">
        <QuickAction label="Create Dashboard" />
        <QuickAction label="Upload CSV" />
        <QuickAction label="Browse Datasets" />
        <QuickAction label="Generate Report" />
      </div>
      <div className="grid grid-cols-2 gap-6">
        <ActivityFeed activities={activities} />
        <div className="ai-search bg-white p-4 rounded shadow">AI search coming soon...</div>
      </div>
    </div>
  );
}
